                UPDATE audit_logs AS a
                SET "CustomerId" = NULL
                WHERE a."CustomerId" IS NOT NULL
                  AND NOT EXISTS (SELECT 1 FROM customers c WHERE c."Id" = a."CustomerId");
            END IF;
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'notifications')
               AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_notifications_leads_LeadId') THEN
                UPDATE notifications AS n
                SET "LeadId" = NULL
                WHERE n."LeadId" IS NOT NULL
                  AND NOT EXISTS (SELECT 1 FROM leads l WHERE l."Id" = n."LeadId");
            END IF;
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'notifications')
               AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_notifications_customers_CustomerId') THEN
                UPDATE notifications AS n
                SET "CustomerId" = NULL
                WHERE n."CustomerId" IS NOT NULL
                  AND NOT EXISTS (SELECT 1 FROM customers c WHERE c."Id" = n."CustomerId");
            END IF;

            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'followups')
               AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_followups_leads_LeadId') THEN
                ALTER TABLE followups ADD CONSTRAINT "FK_followups_leads_LeadId"
                    FOREIGN KEY ("LeadId") REFERENCES leads ("Id") ON DELETE SET NULL;
            END IF;
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'followups')
               AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_followups_customers_CustomerId') THEN
                ALTER TABLE followups ADD CONSTRAINT "FK_followups_customers_CustomerId"
                    FOREIGN KEY ("CustomerId") REFERENCES customers ("Id") ON DELETE SET NULL;
            END IF;
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'audit_logs')
               AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_audit_logs_leads_LeadId') THEN
                ALTER TABLE audit_logs ADD CONSTRAINT "FK_audit_logs_leads_LeadId"
                    FOREIGN KEY ("LeadId") REFERENCES leads ("Id") ON DELETE SET NULL;
            END IF;
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'audit_logs')
               AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_audit_logs_customers_CustomerId') THEN
